import { BooleanColumn, StringColumn, IntegerColumn } from '@servicenow/sdk/core'
import { ActionDefinition, FlowObject, FlowArray } from '@servicenow/sdk/automation'

/**
 * Example 4: Action definition with nested FlowObject containing a FlowArray child
 *
 * This demonstrates a FlowObject that contains a FlowArray as one of its fields.
 */

ActionDefinition({
    $id: Now.ID['action-nested-object-with-array'],
    name: 'fl-action-nested-object-with-array',
    annotation: 'Test action with nested FlowObject containing FlowArray',
    description: 'Demonstrates nested FlowObject with FlowArray child',
    category: 'Testing',
    inputs: {
        taskDetails: FlowObject({
            label: 'Task Details',
            mandatory: true,
            fields: {
                title: StringColumn({
                    label: 'Title',
                    mandatory: true,
                    maxLength: 200,
                }),
                description: StringColumn({
                    label: 'Description',
                    mandatory: false,
                    maxLength: 1000,
                }),
                dueDate: StringColumn({
                    label: 'Due Date',
                    mandatory: false,
                }),
                // FlowArray as a child of FlowObject
                subtasks: FlowArray({
                    label: 'Subtasks',
                    mandatory: false,
                    elementType: StringColumn({
                        label: 'Subtask',
                        maxLength: 200,
                    }),
                    childName: 'subtask_child0',
                }),
                estimatedHours: IntegerColumn({
                    label: 'Estimated Hours',
                    mandatory: false,
                    min: 0,
                    max: 1000,
                }),
            },
        }),
    },
    outputs: {
        success: BooleanColumn({
            label: 'Success',
            mandatory: true,
        }),

        // Output with nested structure
        result: FlowObject({
            label: 'Result',
            mandatory: false,
            fields: {
                id: StringColumn({
                    label: 'ID',
                    mandatory: false,
                }),
                completedSubtasks: FlowArray({
                    label: 'Completed Subtasks',
                    mandatory: false,
                    elementType: StringColumn({
                        label: 'Completed Subtask',
                        maxLength: 200,
                    }),
                    childName: 'completed_subtask_child0',
                }),
            },
        }),
    },
})
